const icons={cutlery:'M5 3l14 18M4 3v5c0 3 4 3 5 1M7 2v5M20 3c-5 1-8 5-5 8l-9 10M20 3c2 4-1 8-5 8',burger:'M3 10c0-9 18-9 18 0H3zM3 14l4 2 5-2 5 2 4-2M3 19h18M4 22h16',pizza:'M3 5c5-4 13-4 18 0L12 22 3 5zM8 6h.1M15 7h.1M11 12h.1',pasta:'M3 10h18c0 7-4 9-9 9s-9-2-9-9zM12 19v3M7 22h10M6 10V2M10 10V2M14 10V2M3 3h18M3 6h18',pin:'M12 22s8-8 8-14a8 8 0 0 0-16 0c0 6 8 14 8 14zM12 5a3 3 0 1 1 0 6 3 3 0 0 1 0-6',phone:'M5 3l4 5-3 3c2 4 3 5 7 7l3-3 5 4c-1 5-5 4-9 2C5 18 1 10 2 6l3-3z',mail:'M2 4h20v16H2V4zM2 5l10 8L22 5',clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20M12 6v7l4 3',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M4 21v-3c0-5 16-5 16 0v3H4z',leaf:'M12 21c-10 0-11-15-1-15s10 15 1 15zM12 6c0-4 2-5 5-5M12 5L8 1',shield:'M12 2L3 6v6c0 6 9 10 9 10s9-4 9-10V6l-9-4zM8 12l3 3 5-6',flame:'M13 2c-8 5-1 8-5 11-2-1-2-3-2-3-8 11 11 17 13 5 1-4-3-7-3-7 0 4-3 5-3 1V2z',grill:'M5 12h14c0 8-14 8-14 0zM4 10h16M8 19l-2 4M16 19l2 4M8 2c-3 3 3 3 0 6M12 2c-3 3 3 3 0 6M16 2c-3 3 3 3 0 6',glass:'M3 3h18L12 14 3 3zM12 14v8M7 22h10M6 7h12',croissant:'M3 16l3-9 4-3 4 0 4 3 3 9-4 2-3-3h-4l-3 3-4-2zM7 7l3 8M17 7l-3 8M10 4v11M14 4v11',check:'M3 5l2 2 4-5M12 5h9M3 15l2 2 4-5M12 15h9',search:'M10 2a8 8 0 1 0 0 16 8 8 0 0 0 0-16M16 16l6 6',compass:'M9 3h6M12 3v5M9 9L4 22M15 9l5 13M8 16h8M12 7a2 2 0 1 0 0 4 2 2 0 0 0 0-4',recycle:'M8 3h6l3 5M15 4l2 4 4-1M20 12l-2 6h-6M15 16l-3 2 3 4M7 19l-4-5 3-5M3 9l3 0 2 3',tractor:'M2 12h11V5H8M14 9h6l2 6h-7M5 12a4 4 0 1 0 0 8 4 4 0 0 0 0-8M18 16a3 3 0 1 0 0 6 3 3 0 0 0 0-6M3 7h6',badge:'M12 2l3 2 4 0 1 4 2 4-2 3-1 4-4 1-3 2-3-2-4-1-1-4-2-3 2-4 1-4 4 0 3-2zM8 12l3 3 5-6'};
document.querySelectorAll('[data-icon]').forEach(el=>{const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',icons[el.dataset.icon]||icons.cutlery);svg.append(path);el.append(svg)});
const dialog=document.querySelector('dialog');const dialogBody=document.querySelector('#dialog-body');
function openDialog(title,text){dialogBody.replaceChildren();const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=text;dialogBody.append(h,p);dialog.showModal()}
document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
let noticeTimer;function notify(text){const el=document.querySelector('#notice');el.textContent=text;el.style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.style.display='none',3500)}
let cart=[];try{const saved=JSON.parse(localStorage.getItem('foodiehub-cart')||'[]');if(Array.isArray(saved))cart=saved}catch{}
document.querySelectorAll('[data-add]').forEach(button=>button.addEventListener('click',()=>{cart.push(button.dataset.add);try{localStorage.setItem('foodiehub-cart',JSON.stringify(cart))}catch{}notify(`${button.dataset.add} added to cart (${cart.length})`)}));
document.querySelectorAll('[data-account]').forEach(button=>button.addEventListener('click',()=>{openDialog(button.dataset.account,'Account services are not connected in this static design preview.');if(cart.length){const list=document.createElement('ul');cart.forEach(name=>{const li=document.createElement('li');li.textContent=name;list.append(li)});const h=document.createElement('h3');h.textContent=`YOUR CART (${cart.length})`;const clear=document.createElement('button');clear.textContent='CLEAR CART';clear.addEventListener('click',()=>{cart=[];try{localStorage.removeItem('foodiehub-cart')}catch{}dialog.close();notify('Cart cleared')});dialogBody.append(h,list,clear)}}));
document.querySelectorAll('[data-enlarge]').forEach(picture=>{function enlarge(){openDialog(picture.dataset.enlarge,'SCHEMATIC WIREFRAME // HIGH-RES SPEC');const clone=picture.cloneNode(true);clone.removeAttribute('tabindex');clone.removeAttribute('role');clone.removeAttribute('data-enlarge');clone.querySelector('.expand-label')?.remove();clone.style.margin='0';dialogBody.append(clone)}picture.addEventListener('click',enlarge);picture.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();enlarge()}})});
const search=document.querySelector('#search');let category='all';
function filterMenu(){const query=search.value.toLowerCase().trim();let visible=0;document.querySelectorAll('.catalogue .product').forEach(card=>{const show=(category==='all'||category===card.dataset.category)&&card.textContent.toLowerCase().includes(query);card.hidden=!show;card.style.display=show?'':'none';if(show)visible++});document.querySelector('#no-results').hidden=visible>0;document.querySelector('#inventory').textContent=category==='all'&&!query?'TOTAL INVENTORY: 24 DISHES':`${visible} DISHES FOUND`}
if(search){search.addEventListener('input',filterMenu);document.querySelectorAll('[data-category-filter]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.categoryFilter;document.querySelectorAll('[data-category-filter]').forEach(tab=>{tab.classList.toggle('dark',tab===button);tab.setAttribute('aria-pressed',String(tab===button))});filterMenu()}));document.querySelectorAll('[data-pagination]').forEach(button=>button.addEventListener('click',()=>notify('The supplied design contains the first page of dishes. Additional catalogue pages are not provided.')))}
document.querySelectorAll('[data-booking-tab]').forEach(button=>button.addEventListener('click',()=>{const isMessage=button.dataset.bookingTab==='message';document.querySelector('.booking-form').classList.toggle('message-mode',isMessage);document.querySelectorAll('[data-booking-tab]').forEach(tab=>{tab.classList.toggle('dark',tab===button);tab.setAttribute('aria-selected',String(tab===button))});document.querySelector('#submit-booking').textContent=isMessage?'SEND MESSAGE':'CONFIRM TABLE RESERVATION →';document.querySelector('#notes-label').textContent=isMessage?'YOUR MESSAGE *':'SPECIAL SEATING NOTES & DIETARY PROTOCOLS';document.querySelector('#notes').required=isMessage;document.querySelector('#booking-date').required=!isMessage}));
document.querySelectorAll('[data-preview-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();openDialog('REQUEST PREPARED','This is a static design preview. Your request has not been sent to a restaurant.')}));
document.querySelector('#promo-form')?.addEventListener('submit',e=>{e.preventDefault();const value=document.querySelector('#promo-code').value.trim().toUpperCase();document.querySelector('#promo-status').textContent=value==='FAMILY25'?'✓ FAMILY25 VERIFIED // 25% OFF FAMILY FEAST':value==='TASTE150'?'✓ TASTE150 VERIFIED // ₹150 OFF • MIN BASKET ₹499':'ⓘ CODE NOT RECOGNIZED // CHECK & RETRY'});
document.querySelector('[data-claim]')?.addEventListener('click',()=>{const input=document.querySelector('#promo-code');input.value='TASTE150';input.scrollIntoView({behavior:'smooth',block:'center'});input.focus({preventScroll:true})});
document.querySelectorAll('[data-zoom]').forEach(button=>button.addEventListener('click',()=>{const pin=button.closest('.map').querySelector('.map-disc');const scale=Math.max(.6,Math.min(1.8,Number(pin.dataset.scale||1)+Number(button.dataset.zoom)*.2));pin.dataset.scale=scale;pin.style.transform=`scale(${scale})`}));
document.querySelector('#banquet-request')?.addEventListener('click',()=>{openDialog('PRIVATE BANQUET INQUIRY','Contact our concierge through the booking terminal to request custom tasting courses and private reception details.');const link=document.createElement('a');link.href='contact.html';link.className='button dark';link.textContent='CONTACT CONCIERGE →';dialogBody.append(link)});
